function day(offset){const d=new Date();d.setDate(d.getDate()+offset);return d.toISOString().slice(0,10)}
let supabaseUser=null;let supabaseProfileError=null;let storageWarned=false;let authMode="signin";let state=loadState();let coachHistory=[];let billingPeriod=state.subscriptionTerm||"monthly";let currentPage="landing";let toastTimer;let appUser=null;let isOwner=false;let catalog=[...productsSeed];let workouts=[...workoutsSeed];
function stateStorageKey(){return supabaseUser?KEY+":"+supabaseUser.id:KEY+":guest"}
function loadState(){try{const saved=JSON.parse(localStorage.getItem(stateStorageKey())||"{}");return {...defaults(),...saved,logs:{...defaults().logs,...(saved.logs||{})}}}catch{return defaults()}}
function save(){localStorage.setItem(stateStorageKey(),JSON.stringify(state));syncRemote()}
let syncTimer;function syncRemote(){if(!supabaseUser?.id)return;clearTimeout(syncTimer);syncTimer=setTimeout(async()=>{const {error}=await supabase.from("vitalyx_profiles").upsert({user_id:supabaseUser.id,email:supabaseUser.email||"",display_name:state.name||"Member",app_data:state,updated_at:new Date().toISOString()},{onConflict:"user_id"});if(error){supabaseProfileError=error;console.error("Supabase profile save failed:",error);if(!storageWarned){storageWarned=true;toast("Could not save to Supabase. Check the included SQL setup and RLS.")}}},600)}
async function loadSupabaseProfile(user){supabaseUser=user;supabaseProfileError=null;storageWarned=false;const base=defaults();let local={};try{local=JSON.parse(localStorage.getItem(stateStorageKey())||"{}")}catch{}const fallbackName=user.user_metadata?.full_name||user.user_metadata?.name||user.email?.split("@")[0]||"Member";state={...base,...local,name:local.name||fallbackName,email:user.email||"",logs:{...base.logs,...(local.logs||{})}};const {data,error}=await supabase.from("vitalyx_profiles").select("app_data,display_name,email").eq("user_id",user.id).maybeSingle();if(error){supabaseProfileError=error;console.error("Supabase profile load failed:",error);return error}if(data){const saved=data.app_data||{};state={...base,...local,...saved,name:data.display_name||saved.name||fallbackName,email:data.email||user.email||"",logs:{...base.logs,...(local.logs||{}),...(saved.logs||{})}}}localStorage.setItem(stateStorageKey(),JSON.stringify(state));syncRemote();return null}
async function openAuthenticatedApp(user){const error=await loadSupabaseProfile(user);renderApp();if(error)toast("Account connected; run supabase.sql to enable cloud profile storage.")}
async function signInGoogle(){const button=$(".google-button");if(button){button.disabled=true;button.setAttribute("aria-busy","true")}showAuthMessage("Connecting to Google…");try{const {error}=await supabase.auth.signInWithOAuth({provider:"google",options:{redirectTo:VITALYX_REDIRECT_URL}});if(error)throw error}catch(error){showAuthMessage(error?.message||"Could not start Google sign-in. Please try again.",true)}finally{if(button){button.disabled=false;button.removeAttribute("aria-busy")}}}
async function submitAuth(event){event.preventDefault();const email=$("#auth-email").value.trim(),password=$("#auth-password").value,name=$("#auth-name")?.value.trim()||"";const submit=$("#auth-submit");submit.disabled=true;showAuthMessage("Connecting securely…");let result;if(authMode==="signup")result=await supabase.auth.signUp({email,password,options:{data:{full_name:name},emailRedirectTo:VITALYX_REDIRECT_URL}});else result=await supabase.auth.signInWithPassword({email,password});submit.disabled=false;if(result.error){showAuthMessage(result.error.message,true);return}if(authMode==="signup"&&!result.data.session){showAuthMessage("Check your email to confirm your account, then sign in.");return}if(result.data.user)await openAuthenticatedApp(result.data.user)}
function showAuthMessage(message,isError=false){const el=$("#auth-message");if(el){el.textContent=message;el.classList.toggle("error",isError)}}
async function signOutUser(){await supabase.auth.signOut();supabaseUser=null;supabaseProfileError=null;state=loadState();renderLanding()}
async function boot(){try{if(window.websim){appUser=await window.websim.getUser();const [user,creator]=await Promise.all([window.websim.getUser(),window.websim.getCreator()]);isOwner=!!user&&!!creator&&user.id===creator.id}}catch{}const {data,error}=await supabase.auth.getSession();if(data?.session?.user){await openAuthenticatedApp(data.session.user);return}authMode="signin";renderAuth();const callbackParams=new URLSearchParams(window.location.search+"&"+window.location.hash.slice(1));const callbackError=callbackParams.get("error_description")||callbackParams.get("error");if(callbackError)showAuthMessage("Google sign-in failed: "+callbackError,true);else if(error){console.error("Supabase session check failed:",error);showAuthMessage("Could not restore your Supabase session: "+error.message,true)}}
function money(n){return "₹"+Number(n||0).toLocaleString("en-IN")}
