function pageContent(page){return ({dashboard:dashboardHTML,nutrition:nutritionHTML,weight:weightHTML,water:waterHTML,wellness:wellnessHTML,workouts:workoutsHTML,schedule:scheduleHTML,progress:progressHTML,diet:dietHTML,coach:coachHTML,store:storeHTML,membership:membershipHTML,achievements:achievementsHTML,settings:settingsHTML,admin:adminHTML,checkout:checkoutHTML})[page]?.()||dashboardHTML()}
function foodTotals(){return state.logs.food.reduce((a,f)=>({cal:a+Number(f.calories||0),protein:a.protein+Number(f.protein||0)}),{cal:0,protein:0})}
function dashboardHTML(){const f=foodTotals(),w=state.logs.weight.at(-1)?.value||68.1,water=state.logs.water.filter(x=>x.date===day(0)).reduce((a,x)=>a+x.value,0),completed=state.logs.workouts.filter(x=>x.date===day(0)).length;return '<section class="welcome"><div><h2>Good morning, '+escapeHtml(state.name.split(" ")[0])+'.</h2><p>Consistency is built from the choices you make today.</p></div><button class="btn btn-primary" data-page="coach">Ask your coach ✦</button></section><div class="stat-grid">'+statCard("Calories",f.cal+"", "/ "+state.calTarget+" kcal", "◷",f.cal/state.calTarget,"Today’s food log")+statCard("Protein",f.protein+"g","/ "+state.proteinTarget+"g","↗",f.protein/state.proteinTarget,"Daily target")+statCard("Water",water.toFixed(1)+"L","/ "+state.waterTarget+"L","◌",water/state.waterTarget,"Hydration")+statCard("Steps","6,420","/ "+state.stepsTarget,"⌖",6420/state.stepsTarget,"A little more movement")+'</div><div class="dash-columns"><section class="panel"><div class="panel-head"><h3>Today&#39;s workout</h3><small>'+completed+' completed today</small></div><div class="workout-hero"><small>25 MIN · BEGINNER · BODYWEIGHT</small><h3>Full-body reset</h3><p>Strengthen the basics and leave room to feel good.</p><button class="btn btn-primary" data-action="complete-workout" data-id="w1">Start workout →</button></div><div style="height:16px"></div><div class="panel-head"><h3>Your daily balance</h3><button class="btn btn-quiet" data-page="nutrition">See details →</button></div><div class="log-list"><div class="log-row"><span>Calories remaining</span><strong>'+Math.max(0,state.calTarget-f.cal)+' kcal</strong></div><div class="log-row"><span>Last night&#39;s sleep</span><strong>7h 24m</strong></div><div class="log-row"><span>Current weight</span><strong>'+w+' kg</strong></div></div></section><section class="panel"><div class="panel-head"><h3>A little nudge</h3><span class="chip">For today</span></div><div class="recommendation"><span class="bulb">✦</span><p>'+(f.protein<state.proteinTarget?"You're "+(state.proteinTarget-f.protein)+"g from your protein goal. Add a snack you enjoy, like yogurt or roasted chickpeas.":"You're on track with protein today. Keep listening to your hunger and energy.")+'</p></div><div class="panel-head"><h3>Quick log</h3></div><div class="quick-grid"><button class="quick" data-modal="food"><b>＋</b>Log food</button><button class="quick" data-modal="water"><b>◌</b>Add water</button><button class="quick" data-modal="weight"><b>⌖</b>Log weight</button><button class="quick" data-modal="mood"><b>☻</b>Log mood</button><button class="quick" data-action="complete-workout" data-id="w1"><b>▦</b>Workout</button><button class="quick" data-page="coach"><b>✦</b>Ask coach</button></div></section></div>'}
function statCard(title,value,target,icon,ratio,foot){return '<article class="stat-card"><div class="stat-head">'+title+'<i>'+icon+'</i></div><div class="stat-value">'+value+'<small> '+target+'</small></div><div class="meter"><span style="width:'+Math.min(100,Math.max(0,ratio*100))+'%"></span></div><div class="stat-foot">'+foot+'</div></article>'}
function nutritionHTML(){const f=foodTotals(),meals=["Breakfast","Lunch","Dinner","Snack"];return '<div class="page-grid"><section class="panel wide"><div class="panel-head"><div><h3>Today&#39;s nutrition</h3><small>Targets are a guide, not a rule.</small></div><button class="btn btn-primary" data-modal="food">＋ Log food</button></div><div class="stat-grid">'+statCard("Calories",f.cal,"/ "+state.calTarget+" kcal","◷",f.cal/state.calTarget,"Daily target")+statCard("Protein",f.protein+"g","/ "+state.proteinTarget+"g","↗",f.protein/state.proteinTarget,"Daily target")+statCard("Carbs","164g","/ 220g","◌",.74,"Estimated from sample data")+statCard("Fat","48g","/ 70g","◍",.69,"Estimated from sample data")+'</div></section>'+meals.map(meal=>'<section class="panel"><div class="panel-head"><h3>'+meal+'</h3><button class="btn btn-quiet" data-modal="food" data-meal="'+meal+'">＋ Add</button></div><div class="log-list">'+(state.logs.food.filter(f=>f.meal===meal).map(f=>'<div class="log-row"><span>'+escapeHtml(f.name)+'<br><small>'+f.time+'</small></span><strong>'+f.calories+' kcal · '+f.protein+'g protein</strong></div>').join("")||'<div class="empty">Nothing logged here yet.</div>')+'</div></section>')+'</div>'}
function weightHTML(){const latest=state.logs.weight.at(-1)?.value||68.1,first=state.logs.weight[0]?.value||latest,target=Number(state.targetWeight)||64;return '<div class="page-grid"><section class="panel wide"><div class="panel-head"><div><h3>Weight trends</h3><small>Steady changes are more sustainable than rapid shifts.</small></div><button class="btn btn-primary" data-modal="weight">＋ Log weight</button></div><div class="stat-grid">'+statCard("Current",latest+" kg","","⌖",.68,"Latest entry")+statCard("Target",target+" kg","","◎",.4,"Your personal goal")+statCard("Change",(latest-first).toFixed(1)+" kg","this period","↗",.5,"Since first logged")+statCard("BMI",(latest/Math.pow((Number(state.height)||168)/100,2)).toFixed(1),"screening measure","◉",.52,"Not a diagnosis")+'</div><svg class="chart" id="weight-chart" viewBox="0 0 600 180" preserveAspectRatio="none"></svg></section><section class="panel"><h3>Log a measurement</h3><div class="field"><label>Height (cm)</label><input id="height-input" type="number" value="'+(state.height||168)+'"></div><div class="field"><label>Target weight (kg)</label><input id="target-weight" type="number" value="'+target+'"></div><button class="btn btn-dark" data-action="save-body">Save goals</button><p style="font-size:11px;color:var(--muted);margin:13px 0 0">BMI is a broad screening measure. It does not account for individual health or body composition.</p></section></div>'}
function waterHTML(){const history=state.logs.water.filter(x=>x.date===day(0));const total=history.reduce((a,x)=>a+x.value,0);return '<div class="page-grid"><section class="panel"><div class="panel-head"><div><h3>Hydration today</h3><small>Find a rhythm that feels right.</small></div><span class="chip">'+total.toFixed(1)+' / '+state.waterTarget+' L</span></div><div style="font:800 42px Manrope;margin:20px 0 8px">'+total.toFixed(1)+'<small style="font:500 16px DM Sans;color:var(--muted)"> liters</small></div><div class="meter" style="height:10px"><span style="width:'+Math.min(100,total/state.waterTarget*100)+'%"></span></div><div class="row" style="margin-top:20px"><button class="btn btn-primary" data-action="add-water" data-amount="0.25">＋ 250 ml</button><button class="btn btn-quiet" data-action="add-water" data-amount="0.5">＋ 500 ml</button></div></section><section class="panel"><h3>Daily target</h3><div class="field"><label>Water goal (liters)</label><input id="water-target" type="number" step="0.1" value="'+state.waterTarget+'"></div><button class="btn btn-dark" data-action="save-water-target">Update target</button><p style="font-size:11px;color:var(--muted);margin-top:13px">Needs vary with activity, climate and health. Your target is a personal reminder, not medical advice.</p></section><section class="panel wide"><div class="panel-head"><h3>Recent hydration</h3><small>Daily totals</small></div><div class="log-list">'+[-6,-5,-4,-3,-2,-1,0].map(d=>{const v=state.logs.water.filter(x=>x.date===day(d)).reduce((a,x)=>a+x.value,0);return '<div class="log-row"><span>'+new Date(day(d)+"T12:00:00").toLocaleDateString(undefined,{weekday:"short",month:"short",day:"numeric"})+'</span><strong>'+v.toFixed(1)+' L</strong></div>'}).join("")+'</div></section></div>'}
function wellnessHTML(){const last=state.logs.mood.at(-1);return '<div class="page-grid"><section class="panel"><div class="panel-head"><h3>How are you feeling?</h3><span class="chip">Today</span></div><div class="quick-grid">'+[["😊","Excellent"],["🙂","Good"],["😐","Neutral"],["😔","Low"],["😡","Stressed"],["😴","Tired"]].map(m=>'<button class="quick" data-action="mood" data-mood="'+m[1]+'"><b>'+m[0]+'</b>'+m[1]+'</button>').join("")+'</div><div class="field"><label>A note for yourself (optional)</label><textarea id="mood-note" placeholder="Anything you&#39;d like to remember?"></textarea></div></section><section class="panel"><div class="panel-head"><h3>Sleep check-in</h3><span class="chip">General wellness</span></div><div class="row"><div class="field"><label>Hours</label><input id="sleep-hours" type="number" step="0.25" value="7.5"></div><div class="field"><label>Quality</label><select id="sleep-quality"><option>Good</option><option>Okay</option><option>Restless</option></select></div></div><button class="btn btn-dark" data-action="log-sleep">Save sleep</button><p style="font-size:11px;color:var(--muted);margin:13px 0 0">A consistent wind-down, dim lights and less late caffeine can support rest.</p></section><section class="panel"><div class="panel-head"><div><h3>Wellness stress indicator</h3><small>Based only on your check-ins, not a diagnosis.</small></div></div><div class="field"><label>Stress level · 1 to 10</label><input id="stress-level" type="range" min="1" max="10" value="4"></div><div id="stress-readout" style="font:750 28px Manrope">4</div><button class="btn btn-primary" data-action="log-stress">Save check-in</button><div class="recommendation" style="margin-top:15px"><span class="bulb">◌</span><p>Try a short walk, a few slow breaths, gentle stretching or a screen break. If stress feels severe or persistent, consider talking with a qualified health professional.</p></div></section><section class="panel"><div class="panel-head"><h3>Recent check-ins</h3></div><div class="log-list">'+(last?state.logs.mood.slice(-5).reverse().map(m=>'<div class="log-row"><span>'+m.mood+' · '+m.date+'</span><strong>'+escapeHtml(m.note||"")+'</strong></div>').join(""):'<div class="empty">Your mood history will appear here.</div>')+'</div><div style="border-top:1px solid var(--line);margin:15px 0"></div><details><summary style="font-size:13px;font-weight:700;cursor:pointer">Optional PCOD wellness notes</summary><p style="font-size:11px;color:var(--muted);line-height:1.6;margin-top:12px">Track general wellbeing only. This does not predict cycles or diagnose a condition and does not replace medical advice.</p><div class="field"><label>Cycle date / note</label><input id="pcod-note" placeholder="Optional, private wellness note"></div><button class="btn btn-quiet" data-action="save-pcod">Save note</button></details></section></div>'}
function workoutsHTML(){return '<div class="panel"><div class="panel-head"><div><h3>Find your next movement</h3><small>Choose a session that matches your day.</small></div><input class="searchbox" id="workout-search" placeholder="Search workouts..." style="max-width:220px"></div><div class="tabs" id="workout-tabs"><button class="tab active" data-filter="All">All</button><button class="tab" data-filter="Beginner">Beginner</button><button class="tab" data-filter="Moderate">Moderate</button><button class="tab" data-filter="Advanced">Advanced</button></div><div class="page-grid" id="workout-list" style="margin-top:14px">'+workoutCards(workouts)+'</div></div>'}
function workoutCards(list){return list.map(w=>'<article class="panel"><div class="panel-head"><span class="chip">'+w.level+' · '+w.minutes+' min</span><span style="font-size:18px">▦</span></div><h3>'+escapeHtml(w.name)+'</h3><p style="font-size:12px;color:var(--muted)">'+escapeHtml(w.desc)+'</p><div class="log-row"><span>'+w.equipment+'</span><span>'+w.muscles+'</span></div><details style="margin-top:12px"><summary style="font-size:12px;cursor:pointer">View exercises</summary><p style="font-size:12px;line-height:1.8;color:var(--muted)">'+w.exercises.map(escapeHtml).join("<br>")+'</p></details><div class="row" style="margin-top:12px"><button class="btn btn-primary" data-action="complete-workout" data-id="'+w.id+'">Start session</button><button class="btn btn-quiet" data-action="schedule-workout" data-id="'+w.id+'">Schedule</button></div></article>').join("")||'<div class="empty">No workouts match that filter.</div>'}
function scheduleHTML(){return '<div class="page-grid"><section class="panel"><div class="panel-head"><h3>Schedule a session</h3></div><div class="field"><label>Workout</label><select id="schedule-workout">'+workouts.map(w=>'<option value="'+w.id+'">'+escapeHtml(w.name)+'</option>').join("")+'</select></div><div class="row"><div class="field"><label>Date</label><input type="date" id="schedule-date" value="'+day(0)+'"></div><div class="field"><label>Time</label><input type="time" id="schedule-time" value="18:00"></div></div><button class="btn btn-dark" data-action="save-schedule">Add to schedule</button></section><section class="panel"><div class="panel-head"><h3>Upcoming</h3></div><div class="log-list">'+(state.schedule.filter(x=>!x.done).sort((a,b)=>a.date.localeCompare(b.date)).map(s=>'<div class="log-row"><span><strong>'+escapeHtml(workouts.find(w=>w.id===s.workout)?.name||s.name)+'</strong><br>'+s.date+' · '+s.time+'</span><button class="btn btn-quiet" data-action="complete-scheduled" data-id="'+s.id+'">Done</button></div>').join("")||'<div class="empty">No sessions scheduled. A little planning can make showing up easier.</div>')+'</div><h3 style="margin-top:22px">Completed</h3><div class="log-list">'+(state.schedule.filter(x=>x.done).slice(-5).map(s=>'<div class="log-row"><span>'+escapeHtml(s.name)+' · '+s.date+'</span><strong>✓</strong></div>').join("")||'<div class="empty">Completed sessions will show here.</div>')+'</div></section></div>'}
function progressHTML(){const f=foodTotals();return '<div class="page-grid"><section class="panel wide"><div class="panel-head"><div><h3>Your progress</h3><small>Progress is personal. Look for patterns, not perfection.</small></div><div class="tabs"><button class="tab active">7 days</button><button class="tab">30 days</button><button class="tab">3 months</button><button class="tab">6 months</button></div></div><svg class="chart" id="progress-chart" viewBox="0 0 600 180" preserveAspectRatio="none"></svg></section><section class="panel"><div class="panel-head"><h3>This week</h3><span class="chip">Sample + your logs</span></div><div class="log-list"><div class="log-row"><span>Workouts completed</span><strong>'+state.logs.workouts.length+' / 5</strong></div><div class="log-row"><span>Average protein today</span><strong>'+f.protein+'g</strong></div><div class="log-row"><span>Average sleep</span><strong>7h 24m</strong></div><div class="log-row"><span>Weight change</span><strong>'+(state.logs.weight.at(-1)?.value-state.logs.weight[0]?.value||0).toFixed(1)+' kg</strong></div><div class="log-row"><span>Habits logged</span><strong>'+Math.min(100,Math.round((state.logs.food.length+state.logs.water.length+state.logs.workouts.length)/12*100))+'%</strong></div></div></section><section class="panel"><div class="panel-head"><h3>Recent activity</h3></div><div class="log-list">'+[...state.logs.workouts.slice(-3).reverse().map(x=>({text:x.name,date:x.date,icon:"▦"})),...state.logs.food.slice(-3).reverse().map(x=>({text:x.name,date:day(0),icon:"◉"}))].map(a=>'<div class="log-row"><span>'+a.icon+' &nbsp;'+escapeHtml(a.text)+'</span><small>'+a.date+'</small></div>').join("")+'</div></section></div>'}
function dietHTML(){return '<div class="panel" style="max-width:850px"><div class="panel-head"><div><h3>Your flexible daily guide</h3><small>General wellness ideas based on your '+escapeHtml(state.goal.toLowerCase())+' goal.</small></div><span class="chip">Sample guidance</span></div><div class="recommendation"><span class="bulb">✦</span><p>This is a general example, not medical nutrition advice. Adjust portions to your needs and preferences; consult a qualified dietitian for individual guidance.</p></div><div class="log-list">'+[["Breakfast","Greek yogurt, berries & oats","~360 kcal · 24g protein"],["Mid-morning","Apple with peanut butter","~190 kcal · 5g protein"],["Lunch","Lentil and grain bowl with greens","~520 kcal · 24g protein"],["Afternoon","Roasted chickpeas or a yogurt","~180 kcal · 12g protein"],["Dinner","Tofu or chicken, vegetables & rice","~620 kcal · 35g protein"]].map(m=>'<div class="log-row"><span><strong>'+m[0]+'</strong><br>'+m[1]+'</span><strong>'+m[2]+'</strong></div>').join("")+'</div><button class="btn btn-dark" style="margin-top:16px" data-action="export-diet">Save guide as text</button></div>'}
function coachHTML(){return '<div class="page-grid"><section class="panel"><div class="panel-head"><div><h3>VITALYX Coach</h3><small>Everyday fitness and wellness guidance</small></div><span class="chip">✦ '+state.plan+'</span></div><div id="chat-messages" class="log-list" style="height:340px;overflow:auto;padding:10px;background:#f7f9f5;border-radius:14px"><div class="recommendation"><span class="bulb">✦</span><p>Hey '+escapeHtml(state.name.split(" ")[0])+'! I can help with workouts, food ideas, protein, sleep and recovery. What are you working on?</p></div></div><div class="tabs" style="margin:12px 0">'+["Beginner workout","Post-workout snack","Protein ideas","Sleep routine"].map(p=>'<button class="tab" data-prompt="'+p+'">'+p+'</button>').join("")+'</div><div class="row"><input class="searchbox" id="coach-input" placeholder="Ask about your wellness routine..."><button class="btn btn-primary" data-action="send-coach">Send</button></div><p style="font-size:10px;color:var(--muted);margin-top:10px">Coach responses are general information, not diagnosis or medical advice. For health concerns, consult a qualified professional.</p></section><section class="panel"><h3>Your context</h3><p style="font-size:13px;color:var(--muted);line-height:1.7">Goal: '+escapeHtml(state.goal)+'<br>Daily protein target: '+state.proteinTarget+'g<br>Today&#39;s protein: '+foodTotals().protein+'g<br>Plan: '+state.plan+'</p><div class="recommendation"><span class="bulb">◎</span><p>VITALYX Coach will answer with general guidance and your saved app context. It will not diagnose conditions or prescribe medication.</p></div></section></div>'}
function storeHTML(){return '<div class="panel"><div class="panel-head"><div><h3>Fitness & nutrition products</h3><small>Demo catalog · verify final labels and prices before launch.</small></div><button class="btn btn-dark" data-action="view-cart">Cart · '+state.cart.reduce((a,x)=>a+x.quantity,0)+' ↗</button></div><div class="store-tools"><input class="searchbox" id="product-search" placeholder="Search products or ingredients"><select id="product-category" class="searchbox" style="max-width:190px"><option>All categories</option>'+[...new Set(catalog.map(p=>p.category))].map(c=>'<option>'+escapeHtml(c)+'</option>').join("")+'</select></div><div class="store-preview" id="store-products">'+catalog.map(storeProduct).join("")+'</div></div>'}
function storeProduct(p){const price=Math.round(p.price*(1-(p.discount||0)/100));return '<article class="product-card"><img src="'+escapeAttr(p.image)+'" alt="'+escapeAttr(p.name)+'" loading="lazy"><div class="product-info"><small>★ '+p.rating+' · '+escapeHtml(p.category)+'</small><h3>'+escapeHtml(p.name)+'</h3><p>'+escapeHtml(p.desc)+'<br>'+(p.nutritionText?escapeHtml(p.nutritionText):escapeHtml(String(p.protein))+' g protein · '+(p.calorieText||p.calories+' kcal')+' / '+escapeHtml(p.serving||p.pack||""))+'</p><strong>'+money(price)+' '+(p.discount?'<del style="color:#9aa59c;font-size:11px">'+money(p.price)+'</del>':"")+'</strong><div class="row" style="margin-top:12px"><button class="btn btn-outline" data-action="product-details" data-id="'+escapeAttr(p.id)+'">Full details</button><button class="btn btn-primary" data-action="add-to-cart" data-id="'+escapeAttr(p.id)+'">Add to cart</button></div><div class="row" style="margin-top:8px"><button class="btn btn-quiet" data-action="buy-product" data-id="'+escapeAttr(p.id)+'">Buy now</button><button class="btn btn-quiet" data-action="wishlist" data-id="'+escapeAttr(p.id)+'">'+(state.wishlist.includes(p.id)?"♥":"♡")+'</button></div></div></article>'}
function membershipHTML(){return '<div class="panel" style="margin-bottom:17px"><div class="panel-head"><div><h3>Your current plan: '+state.plan+'</h3><small>Plans are demo memberships. Checkout uses UPI QR; no payment is processed in this prototype.</small></div><span class="chip">Active</span></div><p style="font-size:13px;color:var(--muted)">Every plan includes a starter exercise guide and diet plan. Pro and Elite add personalized guidance, more programs, coaching and analytics.</p></div><div class="tabs" style="justify-content:flex-end;margin:0 0 14px"><button class="tab '+(billingPeriod==="monthly"?"active":"")+'" data-action="set-billing" data-period="monthly">Monthly</button><button class="tab '+(billingPeriod==="yearly"?"active":"")+'" data-action="set-billing" data-period="yearly">Yearly · save 2 months</button></div><div class="pricing-grid">'+pricingCards()+'</div>'}
function achievementsHTML(){const badges=[["First Workout","Complete your first guided workout",state.logs.workouts.length>=1,"▦"],["7-day streak","Keep your movement routine going",state.logs.workouts.length>=7,"✳"],["Hydration Hero","Reach your water goal for a day",state.logs.water.some(x=>x.value>=state.waterTarget),"◌"],["Protein Pro","Log your daily protein target",foodTotals().protein>=state.proteinTarget,"↗"],["Sleep Champion","Log a restful night's sleep",state.logs.sleep.length>0,"☾"],["10 Workouts","Show up for ten sessions",state.logs.workouts.length>=10,"⌁"]];return '<div class="page-grid">'+badges.map(b=>'<article class="panel" style="opacity:'+(b[2]?1:.62)+'"><div class="feature-icon">'+b[3]+'</div><h3>'+b[0]+' '+(b[2]?"✓":"")+'</h3><p style="color:var(--muted);font-size:12px">'+b[1]+'</p><span class="chip">'+(b[2]?"Earned":"In progress")+'</span></article>').join("")+'</div>'}
function settingsHTML(){return '<div class="page-grid"><section class="panel"><h3>Your profile</h3><div class="field"><label>Name</label><input id="profile-name" value="'+escapeAttr(state.name)+'"></div><div class="field"><label>Fitness goal</label><select id="profile-goal">'+["Weight management","Build strength","Muscle building","General fitness","Better nutrition","Better sleep","Stress management"].map(g=>'<option '+(g===state.goal?"selected":"")+'>'+g+'</option>').join("")+'</select></div><div class="row"><div class="field"><label>Daily calorie target</label><input id="cal-target" type="number" value="'+state.calTarget+'"></div><div class="field"><label>Protein target (g)</label><input id="protein-target" type="number" value="'+state.proteinTarget+'"></div></div><button class="btn btn-dark" data-action="save-profile">Save profile</button></section><section class="panel"><h3>Preferences & privacy</h3><div class="log-row"><span>Water reminders</span><input type="checkbox" id="pref-water" checked></div><div class="log-row" style="margin-top:8px"><span>Workout reminders</span><input type="checkbox" id="pref-workout" checked></div><div class="log-row" style="margin-top:8px"><span>Weekly summary</span><input type="checkbox" id="pref-weekly" checked></div><p style="font-size:11px;color:var(--muted);line-height:1.6;margin-top:14px">Your demo profile stays in this browser. When signed in to Websim, supported wellness data also syncs to this project&#39;s private database. This demo does not handle account passwords or medical records.</p><button class="btn btn-quiet" data-action="export-data">Export my data</button></section></div>'}
function adminHTML(){return '<div class="welcome"><div><h2>Admin studio</h2><p>Project owner access · content edits are stored in the project database.</p></div><span class="chip">Owner verified server-side</span></div><div class="stat-grid">'+statCard("Demo users","1"," active","♙",.2,"Privacy-preserving demo data")+statCard("Products",catalog.length,"published","▣",.6,"Store catalog")+statCard("Workouts",workouts.length,"published","▦",.7,"Workout library")+statCard("Orders","—","private","◷",.1,"No analytics inferred")+'</div><div class="page-grid" style="margin-top:15px"><section class="panel"><div class="panel-head"><h3>Add a workout</h3><span class="chip">Owner only</span></div><div class="field"><label>Title</label><input id="admin-workout-title" placeholder="e.g. Sunday mobility flow"></div><div class="row"><div class="field"><label>Difficulty</label><select id="admin-workout-level"><option>Beginner</option><option>Moderate</option><option>Advanced</option></select></div><div class="field"><label>Duration (min)</label><input id="admin-workout-minutes" type="number" value="25"></div></div><div class="field"><label>Description</label><input id="admin-workout-desc" placeholder="A clear, short description"></div><button class="btn btn-dark" data-action="admin-add-workout">Publish workout</button></section><section class="panel"><div class="panel-head"><h3>Add a store product</h3><span class="chip">Demo inventory</span></div><div class="field"><label>Product name</label><input id="admin-product-title" placeholder="Product title"></div><div class="row"><div class="field"><label>Price (₹)</label><input id="admin-product-price" type="number"></div><div class="field"><label>Category</label><select id="admin-product-category"><option>Protein</option><option>Snacks</option><option>Beverages</option><option>Accessories</option></select></div></div><div class="field"><label>Description</label><input id="admin-product-desc" placeholder="Short description"></div><button class="btn btn-dark" data-action="admin-add-product">Add to store</button></section><section class="panel wide"><div class="panel-head"><h3>Manage catalog</h3><small>New admin items sync to the user library for signed-in visits.</small></div><div class="log-list">'+[...workouts.map(x=>({name:x.name,type:"Workout"})),...catalog.map(x=>({name:x.name,type:"Product"}))].map(x=>'<div class="log-row"><span>'+escapeHtml(x.name)+'</span><span class="chip">'+x.type+'</span></div>').join("")+'</div></section></div>'}
function checkoutHTML(){const check=state.checkout;if(!check)return '<div class="panel empty">No active order. Visit the store or choose a membership to begin.</div>';const total=check.total;return '<div class="checkout-wrap"><button class="checkout-back" data-action="checkout-back">← Back</button><div class="panel" style="margin-bottom:16px"><div class="panel-head"><div><h3>Confirm your order</h3><small>Review the details, then pay using any UPI app.</small></div><span class="chip">Secure UPI checkout</span></div><div class="checkout-grid"><section><div class="field"><label>Customer name</label><input id="checkout-name" placeholder="Name for your order" value="'+escapeAttr(state.name||"")+'"></div><div class="order-lines">'+check.items.map(it=>'<div class="order-line"><span>'+escapeHtml(it.name)+' <span class="chip">× '+it.quantity+'</span></span><strong>'+money(it.price*it.quantity)+'</strong></div>').join("")+'</div><div class="order-total"><span>Total</span><span>'+money(total)+'</span></div><p style="font-size:11px;line-height:1.6;color:var(--muted);margin-top:13px">This demo does not process or verify payments. Confirm only after paying in your UPI app.</p></section><section class="panel qr-panel" style="background:#f8faf6"><h3>Pay '+money(total)+' with UPI</h3><div class="qr-frame"><div id="upi-qr" aria-label="UPI payment QR code"></div></div><p class="qr-instruction">Scan and pay using any UPI app. After paying, tap below to confirm your order.</p><button class="btn btn-primary" style="width:100%" data-action="confirm-whatsapp">Confirm Order on WhatsApp ↗</button></section></div></div></div>'}
function showProductDetails(p){const price=Math.round(p.price*(1-(p.discount||0)/100));const root=document.createElement("div");root.id="product-modal-root";root.className="modal-backdrop";root.innerHTML='<section class="modal product-modal"><button class="product-modal-close" data-action="close-product-details" aria-label="Close">×</button><img src="'+escapeAttr(p.image)+'" alt="'+escapeAttr(p.name)+'"><small class="detail-category">'+escapeHtml(p.category)+' · '+escapeHtml(p.pack||p.serving||"")+'</small><h2>'+escapeHtml(p.name)+'</h2><strong class="detail-price">'+money(price)+'</strong><p>'+escapeHtml(p.desc)+'</p><div class="nutrition-facts"><span><b>'+(p.calorieText||p.calories+' kcal')+'</b><small>Calories / '+escapeHtml(p.serving||"serving")+'</small></span><span><b>'+escapeHtml(String(p.protein))+(p.protein==='N/A'?'':' g')+'</b><small>Protein</small></span><span><b>'+escapeHtml(String(p.carbs))+(p.carbs==='N/A'?'':' g')+'</b><small>Carbs</small></span><span><b>'+escapeHtml(String(p.fat))+(p.fat==='N/A'?'':' g')+'</b><small>Fat</small></span></div><dl><dt>Ingredients / materials</dt><dd>'+escapeHtml(p.ingredients||"See product label.")+'</dd><dt>Allergens</dt><dd>'+escapeHtml(p.allergens||"See product label.")+'</dd><dt>How to use</dt><dd>'+escapeHtml(p.usage||"Follow directions on the product label.")+'</dd><dt>Storage</dt><dd>'+escapeHtml(p.storage||"Follow storage directions on the product label.")+'</dd><dt>Who it is for</dt><dd>'+escapeHtml(p.audience||"See product label.")+'</dd></dl><p class="demo-note">Demo product information. Always check the current product label; seek professional advice for health concerns.</p><button class="btn btn-primary" data-action="add-to-cart" data-id="'+escapeAttr(p.id)+'">Add to cart · '+money(price)+'</button></section>';document.body.append(root);root.addEventListener("click",e=>{if(e.target===root)root.remove()})}
function supportKnowledge(){const products=catalog.map(p=>({name:p.name,category:p.category,price:"₹"+p.price,pack:p.pack,serving:p.serving,calories:p.calorieText||p.calories+" kcal",protein:p.protein==="N/A"?"not applicable":p.protein+" g",carbs:p.carbs==="N/A"?"not applicable":p.carbs+" g",fat:p.fat==="N/A"?"not applicable":p.fat+" g",ingredients:p.ingredients,allergens:p.allergens,howToUse:p.usage,storage:p.storage,for:p.audience,description:p.desc}));return JSON.stringify({notice:"All product and policy information below is fictional demo data and must be replaced with verified business information before launch.",products,policies:{orders:"Order changes may be possible before dispatch but are not guaranteed after fulfillment starts. Cancel before dispatch; after shipping, cancellation is not guaranteed. Contact support promptly with the order number.",shipping:"Demo policy: delivery to serviceable Indian pin codes. Typical estimate is 3–7 business days after dispatch; remote locations may take longer. Checkout/tracking ETA takes priority. Track using the dispatch tracking link.",returns:"Unopened, unused, sealed products may be eligible for return request within 7 days of delivery, subject to approval and category conditions. Opened/used supplements are generally not returnable unless verified defective, damaged, contaminated or incorrectly supplied. Unused shaker may be eligible within 7 days; used items generally are not unless defective. Contact support before sending items back.",damaged:"Report transit damage within 48 hours of delivery. Keep packaging and send order number plus clear photos/videos of outer package, shipping label and damage.",wrongOrMissing:"Contact support with order number and photos of item, package and shipping label. Do not use an incorrect item while awaiting instructions.",refunds:"Approved refunds are initiated to the original payment method where possible. Demo estimate: 5–10 business days after approval; bank/payment provider timelines vary. Refund eligibility and approval must be checked by store support; this chatbot cannot approve or look up refunds.",returnShipping:"For approved wrong-item, defective or transit-damage claims, the business should normally arrange or reimburse return shipping. For voluntary returns, shipping may be deducted only if the final policy permits.",payments:"Payment options and COD depend on what checkout offers and serviceability. If payment succeeded but order confirmation is missing, do not place a duplicate order; retain transaction reference/time and contact support. Report duplicate charges with both transaction references.",account:"Use the website Forgot Password flow. Before dispatch, contact support immediately for address changes; after dispatch, courier limits may apply. Personal information is used for order processing, support and legal/business needs under the site's actual privacy policy. Never share password, OTP, CVV or full card details in chat.",support:"Contact support using the website contact form, support email or WhatsApp shown on the website. Support hours are not specified in this demo knowledge base.",safety:"General product information only, not medical advice. Do not diagnose, claim treatment/cure, promise weight loss/muscle gain, or tell anyone to stop medication. For allergies, medication interactions, pregnancy/breastfeeding, chronic conditions, children or serious symptoms, refer to a qualified healthcare professional. Always verify current package labels. No stock, specific delivery date, coupon, order status or refund approval is connected or known.",general:"Protein selection depends on diet preference, allergies, goals and budget; Pulse Whey contains dairy, PlantPro is plant-based, and Omega Active contains fish/gelatin. Strict vegan customers should verify the package. Pulse Whey has 24 g protein/30 g, PlantPro 22 g/35 g, FitFuel bar 15 g/bar. For healthy exercising adults, a commonly discussed general range is roughly 1.2–2.0 g protein/kg/day, but needs vary and this is not a personal prescription. Total daily intake and overall diet matter more than a narrow post-workout window. Only Pre-Workout Energy is formulated with caffeine; the exact caffeine amount is not listed. Products do not guarantee weight loss or muscle gain and are not automatically meal replacements. Creatine is not protein; consistency matters more than exact timing. Appropriate creatine use with normal fluid intake is not generally considered dehydrating, but stored muscle water may raise scale weight. Do not recommend performance supplements or caffeinated pre-workout to children. Pregnant/breastfeeding customers and customers taking medication should ask a clinician/pharmacist before using supplements."}})}
function fallbackSupportAnswer(text){const q=text.toLowerCase();const product=catalog.find(p=>q.includes(p.name.toLowerCase())||p.name.toLowerCase().split(/[- ]+/).filter(w=>w.length>4).some(w=>q.includes(w)));if(/order status|track my order|where is my order|order number/.test(q))return "I can explain the store policy, but I cannot access live order or courier records here. Please use your tracking link or contact website support with your order number. Never share an OTP, password, CVV or full card number.";if(/cancel/.test(q))return "Demo policy: cancellation is allowed before dispatch. After dispatch it is not guaranteed. Contact support immediately with your order number; I cannot see dispatch status.";if(/return|opened|unopened/.test(q))return "Demo policy: unopened, unused, sealed products may be eligible for a return request within 7 days of delivery, subject to approval. Opened supplements are generally not returnable unless defective, damaged, contaminated or incorrectly supplied. Contact support before sending anything back.";if(/refund|money back|charged twice|payment/.test(q))return "Approved refunds are initiated to the original payment method where possible. The demo estimate is 5–10 business days after approval. I cannot view or approve a refund. For payment issues, do not place a duplicate order; contact support with the transaction reference.";if(/deliver|shipping|ship|how long/.test(q))return "Demo delivery estimate: 3–7 business days after dispatch to serviceable Indian pin codes; remote areas may take longer. Your checkout or tracking ETA takes priority.";if(/damage|damaged|wrong item|missing item/.test(q))return "Please keep the packaging and contact support with your order number and clear photos of the product, outer package and shipping label. Report transit damage within 48 hours. Do not use a wrong item while waiting for instructions.";if(/allerg|pregnan|breastfeed|medication|medicine|diagnos|symptom|child|children/.test(q))return "I can share label information but cannot assess personal medical safety. Please check the current package and ask a qualified healthcare professional or pharmacist, especially for allergies, medication, pregnancy/breastfeeding, children or health conditions.";if(product)return product.name+" is "+money(product.price)+" for "+(product.pack||product.serving)+". Per "+product.serving+": "+(product.calorieText||product.calories+" kcal")+", "+product.protein+" g protein, "+product.carbs+" g carbs and "+product.fat+" g fat. Ingredients: "+product.ingredients+" Allergens: "+product.allergens;return "I don't have enough verified information to answer that accurately. Please contact support using the contact form, email or WhatsApp shown on the website."}
let supportHistory=[];async function sendSupportMessage(text){const input=$("#support-input"),messages=$("#support-messages");text=(text||input?.value||"").trim();if(!text||!messages)return;if(input)input.value="";messages.insertAdjacentHTML("beforeend",'<div class="support-user">'+escapeHtml(text)+'</div>');supportHistory.push({role:"user",content:text});supportHistory=supportHistory.slice(-10);const pending=document.createElement("div");pending.className="support-bubble support-pending";pending.textContent="Checking the product and policy information…";messages.append(pending);let answer=fallbackSupportAnswer(text);try{if(window.websim?.chat?.completions){const result=await window.websim.chat.completions.create({messages:[{role:"system",content:"You are the VITALYX fitness-store customer support chatbot. Answer politely and concisely using ONLY the verified knowledge base supplied below. This is fictional demo product/policy information; clearly say demo policy when relevant. Never invent prices, ingredients, nutrition, allergens, stock, discounts, specific delivery dates, account/order status, tracking, refund decisions, medical facts, or contact details. You cannot access orders, inventory, payment gateways, courier tracking or approve cancellations/returns/refunds. Say that plainly and direct customers to website support for account-specific help. For health questions, only provide the listed general product-label facts, never diagnose/prescribe/claim treatment or cure; advise a qualified healthcare professional for allergies, medicines, pregnancy/breastfeeding, chronic conditions, children or serious symptoms. Never ask for password, OTP, CVV or full card number. If the answer is not in the knowledge base, say you don't have enough verified information and refer to support. KNOWLEDGE BASE: "+supportKnowledge()},...supportHistory]});answer=result.content||answer}}catch{}supportHistory.push({role:"assistant",content:answer});supportHistory=supportHistory.slice(-10);pending.remove();messages.insertAdjacentHTML("beforeend",'<div class="support-bubble">'+escapeHtml(answer)+'</div>');messages.scrollTop=messages.scrollHeight}
function bindGlobal(){document.body.classList.toggle("theme-dark",!!state.dark);if(!$("#support-chat")){document.body.insertAdjacentHTML("beforeend",'<div id="support-chat" class="support-chat"><button class="support-launch" data-action="support-toggle" aria-label="Open VITALYX support chat">✦<span>Ask us</span></button><section class="support-panel" id="support-panel" aria-label="VITALYX customer support" hidden><header class="support-head"><div><strong>VITALYX Support</strong><small>Products, delivery & returns</small></div><button data-action="support-close" aria-label="Close chat">×</button></header><div class="support-messages" id="support-messages"><div class="support-bubble">Hi! Ask me about products, ingredients, orders, delivery, returns or refunds. This catalog and its policies are demo information.</div><div class="support-prompts"><button data-support-prompt="What protein products do you have?">Protein products</button><button data-support-prompt="What is your return policy?">Return policy</button></div></div><form class="support-form" id="support-form"><input id="support-input" autocomplete="off" placeholder="Ask a question..." aria-label="Ask a question"><button type="submit" aria-label="Send message">↑</button></form></section></div>')}}
function escapeHtml(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}function escapeAttr(v){return escapeHtml(v).replace(/\n/g," ")}
function svgChart(values){const width=600,height=180,pad=26;const min=Math.min(...values)-.4,max=Math.max(...values)+.4;const pts=values.map((v,i)=>[pad+i*(width-2*pad)/(values.length-1),height-pad-(v-min)/(max-min)*(height-2*pad)]);return '<defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#9bd674" stop-opacity=".3"/><stop offset="1" stop-color="#9bd674" stop-opacity="0"/></linearGradient></defs>'+[40,80,120,160].map(y=>'<line class="gridline" x1="0" x2="600" y1="'+y+'" y2="'+y+'"/>').join("")+'<path class="area" d="M '+pts.map(p=>p.join(" ")).join(" L ")+' L '+pts.at(-1)[0]+' 180 L '+pts[0][0]+' 180 Z"/><path class="line" d="M '+pts.map(p=>p.join(" ")).join(" L ")+'"/>'+pts.map((p,i)=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="4" fill="#79b74e"/><text x="'+p[0]+'" y="174" text-anchor="middle">'+(i+1===values.length?"Today":i+1)+"</text>").join("")}
function drawChart(){const svg=$("#weight-chart")||$("#progress-chart");if(svg)svg.innerHTML=svgChart((state.logs.weight.length?state.logs.weight.map(w=>Number(w.value)):[68.6,68.4,68.2,68.3,68.1]));}
function modal(type,extra={}){const labels={food:"Log food",water:"Add water",weight:"Log weight",mood:"Log mood"};let body="";if(type==="food")body='<div class="field"><label>Food</label><input id="modal-food-name" placeholder="e.g. Banana and peanut butter"></div><div class="row"><div class="field"><label>Meal</label><select id="modal-food-meal">'+["Breakfast","Lunch","Dinner","Snack"].map(x=>'<option '+(x===extra.meal?"selected":"")+'>'+x+'</option>').join("")+'</select></div><div class="field"><label>Calories</label><input id="modal-food-cal" type="number" placeholder="250"></div><div class="field"><label>Protein (g)</label><input id="modal-food-protein" type="number" placeholder="12"></div></div>';
if(type==="water")body='<p>Log a glass of water to your daily total.</p><div class="field"><label>Amount (liters)</label><input id="modal-water-amount" type="number" step="0.05" value="0.25"></div>';
if(type==="weight")body='<div class="field"><label>Weight (kg)</label><input id="modal-weight-value" type="number" step="0.1" value="'+(state.logs.weight.at(-1)?.value||68.1)+'"></div>';
if(type==="mood")body='<div class="field"><label>Mood</label><select id="modal-mood">'+["Excellent","Good","Neutral","Low","Stressed","Tired"].map(x=>'<option '+(x===extra.mood?"selected":"")+'>'+x+'</option>').join("")+'</select></div><div class="field"><label>Note (optional)</label><input id="modal-mood-note" placeholder="A quick note to yourself"></div>';
$("#modal-root")?.remove();const root=document.createElement("div");root.id="modal-root";root.className="modal-backdrop";root.innerHTML='<section class="modal"><h2>'+labels[type]+'</h2><p>Add a little detail to your daily log.</p>'+body+'<div class="modal-actions"><button class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-modal" data-type="'+type+'">Save entry</button></div></section>';document.body.append(root);root.addEventListener("click",e=>{if(e.target===root)root.remove()})}
function startCheckout(items,kind){const clean=items.map(i=>({id:i.id,name:i.name,price:Number(i.price),quantity:Number(i.quantity)||1,kind}));state.checkout={items:clean,total:clean.reduce((a,i)=>a+i.price*i.quantity,0),kind};save();renderApp("checkout");setTimeout(()=>{const uri='upi://pay?pa=pasrijasaksham777-1@oksbi&pn=VITALYX&am='+state.checkout.total.toFixed(2)+'&cu=INR&tn='+encodeURIComponent("VITALYX "+kind+" order");const qr=$("#upi-qr");if(qr&&window.QRCode)new QRCode(qr,{text:uri,width:190,height:190,colorDark:"#17251e",colorLight:"#ffffff",correctLevel:QRCode.CorrectLevel.M});else if(qr)qr.innerHTML='<a href="'+uri+'">Open UPI payment</a>'},50)}
function addWater(amount){state.logs.water.push({date:day(0),value:Number(amount)});save();renderApp(currentPage);toast("Water added to today's log")}
function finishWorkout(id){const w=workouts.find(x=>x.id===id)||workouts[0];state.logs.workouts.push({id:crypto.randomUUID(),workoutId:id,name:w.name,date:day(0),minutes:w.minutes});if(state.logs.workouts.length===1&&!state.achievements.includes("First Workout"))state.achievements.push("First Workout");save();renderApp(currentPage);toast("Session completed. Nice work!")}
function saveModal(type){if(type==="food"){const name=$("#modal-food-name").value.trim();const calories=Number($("#modal-food-cal").value),protein=Number($("#modal-food-protein").value)||0;if(!name||!Number.isFinite(calories)||calories<0){toast("Add a food name and valid calories");return}state.logs.food.push({id:crypto.randomUUID(),name,meal:$("#modal-food-meal").value,calories,protein,time:new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})})}if(type==="water"){const amount=Number($("#modal-water-amount").value);if(!amount||amount<0||amount>5){toast("Enter an amount up to 5 liters");return}state.logs.water.push({date:day(0),value:amount})}if(type==="weight"){const value=Number($("#modal-weight-value").value);if(!value||value<25||value>350){toast("Enter a valid weight");return}state.logs.weight.push({date:day(0),value})}if(type==="mood")state.logs.mood.push({date:day(0),mood:$("#modal-mood").value,note:$("#modal-mood-note").value.trim(),time:new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})});save();$("#modal-root").remove();renderApp(currentPage);toast("Your log has been updated")}
function saveSchedule(){const id=$("#schedule-workout").value,w=workouts.find(x=>x.id===id);state.schedule.push({id:crypto.randomUUID(),workout:id,name:w?.name||"Workout",date:$("#schedule-date").value,time:$("#schedule-time").value,done:false});save();renderApp("schedule");toast("Workout added to your schedule")}
async function sendCoach(){const input=$("#coach-input"),text=input.value.trim();if(!text)return;const msgs=$("#chat-messages");msgs.insertAdjacentHTML("beforeend",'<div class="log-row"><strong>You</strong><span>'+escapeHtml(text)+'</span></div>');coachHistory.push({role:"user",content:text});coachHistory=coachHistory.slice(-10);input.value="";let answer="I can help you build a balanced routine. Try choosing a manageable next step, then adjust based on how you feel. For persistent symptoms or medical questions, please speak with a qualified professional.";try{if(window.websim?.chat?.completions){const result=await window.websim.chat.completions.create({messages:[{role:"system",content:"You are VITALYX Coach. Offer safe, concise general fitness, nutrition and wellness guidance. Never diagnose, prescribe medication, promote rapid weight loss, or replace a clinician or dietitian. User context: goal "+state.goal+", protein target "+state.proteinTarget+" g, today's logged protein "+foodTotals().protein+" g. Keep advice practical and supportive."},...coachHistory]});answer=result.content||answer}}catch{}coachHistory.push({role:"assistant",content:answer});coachHistory=coachHistory.slice(-10);msgs.insertAdjacentHTML("beforeend",'<div class="recommendation"><span class="bulb">✦</span><p>'+escapeHtml(answer)+'</p></div>');msgs.scrollTop=msgs.scrollHeight}
function addToCart(product){const existing=state.cart.find(x=>x.id===product.id);if(existing)existing.quantity++;else state.cart.push({id:product.id,name:product.name,price:Math.round(product.price*(1-(product.discount||0)/100)),quantity:1});save();$("#product-modal-root")?.remove();renderApp("store");toast("Added to your cart")}
function orderWhatsApp(){const name=$("#checkout-name").value.trim();if(name)state.name=name;const c=state.checkout;if(!c)return;if(c.kind==="membership"&&state.pendingPlan){state.plan=state.pendingPlan;state.subscriptionTerm=billingPeriod;state.pendingPlan=null;}const lines=["Hello VITALYX, I'd like to confirm my order:","",...(name?["Customer: "+name,""]:[]),...c.items.map(i=>"• "+i.name+" × "+i.quantity+" — "+money(i.price*i.quantity)),"","Total: "+money(c.total),"Order time: "+new Date().toLocaleString(),"","Thanks for your ordering from us, it was a pleasure dealing with you."];const url="https://wa.me/919817322095?text="+encodeURIComponent(lines.join("\n"));const donePage=c.kind==="membership"?"membership":"store";const payload={name:name||"",items:c.items.map(({name,quantity,price})=>({name,quantity,price})),total:c.total,createdAt:new Date().toISOString()};try{fetch("/api/orders",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload),keepalive:true}).catch(()=>{})}catch{}window.open(url,"_blank","noopener,noreferrer");state.checkout=null;state.cart=[];save();toast("Order details opened in WhatsApp");setTimeout(()=>renderApp(donePage),350)}
function updateStore(){const q=$("#product-search")?.value.toLowerCase()||"",cat=$("#product-category")?.value||"All categories";const list=catalog.filter(p=>(cat==="All categories"||p.category===cat)&&(p.name+" "+p.desc+" "+p.category+" "+p.ingredients+" "+p.allergens).toLowerCase().includes(q));$("#store-products").innerHTML=list.map(storeProduct).join("")||'<div class="empty">No products found. Try another search.</div>'}
async function changePage(page){if(page==="store"||page==="admin")await loadCatalog();renderApp(page);document.querySelector("#sidebar")?.classList.remove("open")}
async function loadCatalog(){try{const r=await fetch("/api/catalog");if(r.ok){const body=await r.json();for(const item of body.items){if(item.kind==="product"&&!catalog.some(x=>x.id===item.id))catalog.push(item);if(item.kind==="workout"&&!workouts.some(x=>x.id===item.id))workouts.push(item)}}}catch{}}
function adminCreate(kind){if(!isOwner){toast("Admin access is restricted to the project owner");return}let item;if(kind==="workout"){const name=$("#admin-workout-title").value.trim();if(!name){toast("Add a workout title");return}item={id:crypto.randomUUID(),name,level:$("#admin-workout-level").value,minutes:Number($("#admin-workout-minutes").value)||25,desc:$("#admin-workout-desc").value.trim(),category:"Strength",equipment:"Choose your setup",muscles:"Full body",exercises:["Add exercise details in your program notes"]}}else{const name=$("#admin-product-title").value.trim(),price=Number($("#admin-product-price").value);if(!name||!price){toast("Add a product name and price");return}item={id:crypto.randomUUID(),name,price,category:$("#admin-product-category").value,discount:0,rating:5,protein:0,calories:0,serving:"1 item",desc:$("#admin-product-desc").value.trim()||"Demo product",image:"https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=700&q=80"}}const k=kind==="workout"?"workout":"product";if(appUser?.id)fetch("/api/admin/catalog",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({kind:k,item})}).catch(()=>{});if(k==="workout")workouts.unshift(item);else catalog.unshift(item);renderApp("admin");toast(kind+" added to the catalog")}
function exportText(){const text=["VITALYX · My flexible diet guide","Breakfast: Greek yogurt, berries & oats","Mid-morning: Apple with peanut butter","Lunch: Lentil and grain bowl with greens","Afternoon: Roasted chickpeas or yogurt","Dinner: Tofu or chicken, vegetables & rice","","General wellness guidance, not medical nutrition advice."].join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([text],{type:"text/plain"}));a.download="vitalyx-diet-guide.txt";a.click();URL.revokeObjectURL(a.href)}

document.addEventListener("click",e=>{const page=e.target.closest("[data-page]");if(page){e.preventDefault();changePage(page.dataset.page);return}const modalBtn=e.target.closest("[data-modal]");if(modalBtn){modal(modalBtn.dataset.modal,{meal:modalBtn.dataset.meal});return}const prompt=e.target.closest("[data-prompt]");if(prompt){$("#coach-input").value=prompt.dataset.prompt;sendCoach();return}const supportPrompt=e.target.closest("[data-support-prompt]");if(supportPrompt){sendSupportMessage(supportPrompt.dataset.supportPrompt);return}const filter=e.target.closest("[data-filter]");if(filter){$$('#workout-tabs .tab').forEach(x=>x.classList.toggle("active",x===filter));const list=filter.dataset.filter==="All"?workouts:workouts.filter(w=>w.level===filter.dataset.filter);$("#workout-list").innerHTML=workoutCards(list);return}const b=e.target.closest("[data-action]");if(!b)return;const a=b.dataset.action;if(a==="support-toggle"){$("#support-panel").hidden=false;$("#support-input")?.focus()}if(a==="support-close")$("#support-panel").hidden=true;if(a==="product-details"){const p=catalog.find(x=>x.id===b.dataset.id);if(p)showProductDetails(p)}if(a==="close-product-details")$("#product-modal-root")?.remove();if(a==="enter"){if(supabaseUser)renderApp(b.dataset.page||"dashboard");else{authMode="signin";renderAuth()}return}if(a==="home")renderLanding();if(a==="auth-toggle"){authMode=authMode==="signup"?"signin":"signup";renderAuth()}if(a==="google-sign-in")signInGoogle();if(a==="sign-out")signOutUser();if(a==="theme"){state.dark=!state.dark;save();document.body.classList.toggle("theme-dark",state.dark);b.textContent=state.dark?"☼":"☾"}if(a==="menu")$("#sidebar").classList.toggle("open");if(a==="close-modal")$("#modal-root").remove();if(a==="save-modal")saveModal(b.dataset.type);if(a==="add-water")addWater(b.dataset.amount);if(a==="complete-workout")finishWorkout(b.dataset.id);if(a==="save-schedule")saveSchedule();if(a==="schedule-workout"){renderApp("schedule");$("#schedule-workout").value=b.dataset.id}if(a==="complete-scheduled"){const s=state.schedule.find(x=>x.id===b.dataset.id);if(s){s.done=true;state.logs.workouts.push({id:crypto.randomUUID(),workoutId:s.workout,name:s.name,date:day(0),minutes:workouts.find(w=>w.id===s.workout)?.minutes||20});save();renderApp("schedule");toast("Workout marked complete")}}if(a==="log-sleep"){state.logs.sleep.push({date:day(-1),hours:Number($("#sleep-hours").value),quality:$("#sleep-quality").value});save();toast("Sleep log saved")}if(a==="log-stress"){state.logs.stress.push({date:day(0),level:Number($("#stress-level").value),note:""});save();toast("Wellness check-in saved")}if(a==="mood"){state.logs.mood.push({date:day(0),mood:b.dataset.mood,note:$("#mood-note")?.value||"",time:new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})});save();renderApp("wellness");toast("Mood check-in saved")}if(a==="save-pcod"){const note=$("#pcod-note").value.trim();if(note){state.pcod=[...(state.pcod||[]),{date:day(0),note}];save();toast("Private wellness note saved")}}if(a==="save-body"){state.height=Number($("#height-input").value)||168;state.targetWeight=Number($("#target-weight").value)||64;save();renderApp("weight");toast("Body goals updated")}if(a==="save-water-target"){state.waterTarget=Number($("#water-target").value)||2.5;save();renderApp("water");toast("Hydration target updated")}if(a==="save-profile"){state.name=$("#profile-name").value.trim()||state.name;state.goal=$("#profile-goal").value;state.calTarget=Number($("#cal-target").value)||2100;state.proteinTarget=Number($("#protein-target").value)||120;save();renderApp("settings");toast("Profile saved")}if(a==="set-billing"){billingPeriod=b.dataset.period;renderApp("membership")}if(a==="send-coach")sendCoach();if(a==="export-diet")exportText();if(a==="export-data"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:"application/json"}));a.download="vitalyx-data.json";a.click();URL.revokeObjectURL(a.href)}if(a==="buy-plan"){if(b.dataset.plan==="Free")return;const p=({Pro:399,Elite:799}[b.dataset.plan]||0)*(billingPeriod==="yearly"?10:1);state.pendingPlan=b.dataset.plan;startCheckout([{id:"membership-"+b.dataset.plan,name:b.dataset.plan+" membership · "+billingPeriod,price:p,quantity:1}],"membership")}if(a==="add-to-cart"){const p=catalog.find(x=>x.id===b.dataset.id);if(p)addToCart(p)}if(a==="buy-product"){const p=catalog.find(x=>x.id===b.dataset.id);if(p)startCheckout([{...p,price:Math.round(p.price*(1-(p.discount||0)/100)),quantity:1}],"product")}if(a==="wishlist"){state.wishlist=state.wishlist.includes(b.dataset.id)?state.wishlist.filter(x=>x!==b.dataset.id):[...state.wishlist,b.dataset.id];save();renderApp("store");toast("Wishlist updated")}if(a==="view-cart"){if(!state.cart.length){toast("Your cart is empty");return}startCheckout(state.cart,"product")}if(a==="confirm-whatsapp")orderWhatsApp();if(a==="checkout-back"){state.checkout=null;renderApp(state.pendingPlan?"membership":"store");state.pendingPlan=null}if(a==="admin-add-workout")adminCreate("workout");if(a==="admin-add-product")adminCreate("product")});
document.addEventListener("input",e=>{if(e.target.id==="stress-level")$("#stress-readout").textContent=e.target.value;if(e.target.id==="product-search"||e.target.id==="product-category")updateStore();if(e.target.id==="workout-search"){const q=e.target.value.toLowerCase();$("#workout-list").innerHTML=workoutCards(workouts.filter(w=>(w.name+" "+w.desc+" "+w.muscles).toLowerCase().includes(q)))}});
document.addEventListener("change",e=>{if(e.target.id==="product-category")updateStore()});
document.addEventListener("submit",e=>{if(e.target.id==="support-form"){e.preventDefault();sendSupportMessage()}if(e.target.id==="auth-form")submitAuth(e)});
boot();